/* @lc app=leetcode id=3398 lang=kotlin */ class Solution { fun minLength(s: String, numOps: Int): Int = (s.indices.filter { it == 0 || s[it] != s[it - 1] } + s.length).zipWithNext { a, b -> b - a }.let { runs -> s.indices.count { (s[it] - '0') != it % 2 }.let { a -> minOf(a, s.length - a) }.let { alt -> generateSequence(1 to s.length) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if ((if (m == 1) alt else runs.sumOf { it / (m + 1) }) <= numOps) lo to m else m + 1 to hi } }.last().first } } }